261	fn select_packages<'w, R: CommandRunner, D: DependencyResolver>(
262	    workspace: &'w Workspace<'_, R, D>,
263	    decision: &ReleaseDecisionV1,
264	) -> Result<Selection<'w>, GraphError> {
265	    let mut selected = BTreeMap::new();
266	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
267	    let mut owners = Owners::new();
268	    for package in workspace.graph.packages() {
269	        let ids = crate::commands::release_decision::release_package_ids(&workspace.identity, package)?;
270	        if let Some(owner) = ids
271	            .iter()
272	            .find(|id| decision.entries.iter().any(|entry| &entry.package == *id))
273	        {
274	            owners.insert(package.id.clone(), owner.clone());
275	        }
276	        // Dedup: `release_package_ids` maps every canonical manifest, so two sharing an ecosystem would repeat an identity.
277	        for id in ids.into_iter().collect::<BTreeSet<_>>() {
278	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
279	                selected.insert(id.clone(), (package, entry.target_version.clone()));
280	                package_ids.entry(package.id.clone()).or_default().push(id);
281	            }
282	        }
283	    }
284	    for entry in &decision.entries {
285	        let id = &entry.package;
286	        if !selected.contains_key(id) {
287	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
288	        }
289	    }
290	    Ok(Selection {
291	        selected,
292	        package_ids,
293	        owners,
294	    })
295	}
