335	/// A prerelease publishes under the tag its first identifier names (`1.0.0-beta.2` -> `beta`), `next` when that is not a
336	/// plain word, and never `latest`; a stable version takes the registry default.
337	fn npm_dist_tag(version: &Version) -> Option<String> {
338	    if !version.is_prerelease() {
339	        return None;
340	    }
341	    let prerelease = version.render().split_once('-').map_or("", |(_, rest)| rest);
342	    let label: String = prerelease
343	        .chars()
344	        .take_while(char::is_ascii_alphabetic)
345	        .collect::<String>()
346	        .to_ascii_lowercase();
347	    Some(if label.is_empty() || label == "latest" {
348	        "next".to_string()
349	    } else {
350	        label
351	    })
352	}
